describe('Table Row Expansion - Nested Details', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="table-container"]').should('be.visible');
  });

  it('should expand a row and display nested details', () => {
    cy.get('[data-testid="table-row"]').first().within(() => {
      cy.get('[data-testid="expand-button"]').click();
    });

    cy.get('[data-testid="nested-details"]').should('be.visible');
    cy.get('[data-testid="nested-details"]').should('contain', 'Details');
  });

  it('should collapse an expanded row when clicking expand button again', () => {
    cy.get('[data-testid="table-row"]').first().within(() => {
      cy.get('[data-testid="expand-button"]').click();
    });

    cy.get('[data-testid="nested-details"]').should('be.visible');

    cy.get('[data-testid="table-row"]').first().within(() => {
      cy.get('[data-testid="expand-button"]').click();
    });

    cy.get('[data-testid="nested-details"]').should('not.be.visible');
  });

  it('should expand multiple rows independently', () => {
    cy.get('[data-testid="table-row"]').eq(0).within(() => {
      cy.get('[data-testid="expand-button"]').click();
    });

    cy.get('[data-testid="table-row"]').eq(0).find('[data-testid="nested-details"]').should('be.visible');

    cy.get('[data-testid="table-row"]').eq(1).within(() => {
      cy.get('[data-testid="expand-button"]').click();
    });

    cy.get('[data-testid="table-row"]').eq(0).find('[data-testid="nested-details"]').should('be.visible');
    cy.get('[data-testid="table-row"]').eq(1).find('[data-testid="nested-details"]').should('be.visible');
  });

  it('should display correct nested content for each row', () => {
    cy.get('[data-testid="table-row"]').first().within(() => {
      cy.get('[data-testid="row-id"]').invoke('text').as('rowId');
      cy.get('[data-testid="expand-button"]').click();
    });

    cy.get('[data-testid="nested-details"]').within(() => {
      cy.get('[data-testid="detail-item"]').should('have.length.greaterThan', 0);
      cy.get('[data-testid="detail-item"]').first().should('be.visible');
    });
  });

  it('should handle edge case with empty nested details', () => {
    cy.get('[data-testid="table-row"]').contains('[data-testid="row-status"]', 'Empty').parent().within(() => {
      cy.get('[data-testid="expand-button"]').click();
    });

    cy.get('[data-testid="nested-details"]').should('be.visible');
    cy.get('[data-testid="nested-details"]').should('contain', 'No details available');
  });
});
